{
  "title": "Marcar uma visita ao apartamento",
  "situation": "Você viu um anúncio de um apartamento em Chicago. Ligue para Emma para perguntar se ele ainda está disponível, saber o valor do aluguel e o que está incluído, e marcar uma visita.",
  "character": {
    "name": "Emma",
    "role": "locadora",
    "place": "Maple Avenue Apartments"
  },
  "characterBrief": "Emma is friendly, patient, and direct. Speak at A2 level using short sentences, common words, and simple structures. The apartment in the ad is still available for rent. It is a one-bedroom, one-bathroom apartment at 1847 North Maple Avenue, Chicago, IL 60614. Rent is $1,450 per month. Water and trash are included; electricity and internet are not included. If the learner asks to view it on Wednesday at 5:30 p.m., say warmly that this time is already booked, then offer Thursday at 6 p.m. or Saturday at 11 a.m. If asked about other viewing times, those are the only available times. Nothing is needed for the viewing; the learner can just arrive at the address. Answer the learner's questions, but do not ask or book on their behalf. Let the learner choose and confirm an available time. Wrap up with a friendly confirmation of the chosen day and time, and say goodbye.",
  "objectives": [
    {
      "label": "Check Availability",
      "description": "Pergunte se o apartamento do anúncio ainda está disponível."
    },
    {
      "label": "Ask About Rent",
      "description": "Pergunte o valor do aluguel e o que está incluído."
    },
    {
      "label": "Book a Viewing",
      "description": "Peça uma visita e confirme um dia e horário disponíveis."
    }
  ],
  "openingLine": "Hi, this is Emma. How can I help?",
  "hints": [
    "Is the apartment still available?",
    "How much is the rent, and what is included?",
    "Can I see it on Wednesday at 5:30 p.m.?",
    "Thursday at 6 works for me."
  ]
}

{
  "title": "Call to Rent an Apartment",
  "situation": "You found an apartment listing in Mexico City. Call the landlord to check if it’s available, ask about the costs and what’s included, and arrange a viewing.",
  "character": {
    "name": "Sofía",
    "role": "landlord",
    "place": "Colonia Narvarte"
  },
  "characterBrief": "Sofía is friendly, patient, and speaks at an A2 level using short, clear sentences. The apartment is available now at Calle Tajín 214, apartment 3, in Colonia Narvarte, Mexico City. It has one bedroom. Rent is $14,000 MXN per month, and the deposit is $14,000 MXN. The rent includes building maintenance and water; electricity, gas, and internet are not included. No documents or payment are needed for a viewing. Viewings are available Tuesday through Friday from 10:00 a.m. to 5:00 p.m. and this Saturday at 11:00 a.m. or 1:30 p.m. The first time the learner suggests this Saturday at 12:00 p.m., say that time is already taken and offer 1:30 p.m. instead. Answer questions without volunteering information the learner has not asked for, and let the learner ask and agree to the viewing time. To wrap up, briefly confirm the agreed day and time and say goodbye.",
  "objectives": [
    {
      "label": "Confirmar disponibilidad",
      "description": "Ask if the apartment is still available."
    },
    {
      "label": "Preguntar por los costos",
      "description": "Ask how much the monthly rent and deposit cost."
    },
    {
      "label": "Preguntar qué incluye",
      "description": "Ask what is included in the rent."
    },
    {
      "label": "Acordar una visita",
      "description": "Suggest a viewing this Saturday at noon, then accept the 1:30 p.m. alternative."
    }
  ],
  "openingLine": "Hola, soy Sofía, la dueña. ¿En qué te ayudo?",
  "hints": [
    "¿Sigue disponible el departamento?",
    "¿Cuánto es la renta y el depósito?",
    "¿Qué incluye la renta?",
    "¿Puedo verlo el sábado a las doce?",
    "Sí, a la una y media está bien."
  ]
}

{
  "title": "Get a Table, Order, and Pay",
  "situation": "You are at Sabor da Praça in São Paulo. Ask server Ana for a table for two, order lunch, ask for the bill, and pay with Pix.",
  "character": {
    "name": "Ana",
    "role": "server",
    "place": "Sabor da Praça"
  },
  "characterBrief": "Speak Brazilian Portuguese at A1 level, using short, simple sentences and common words. Be warm and informal. The restaurant is Sabor da Praça at Rua Harmonia, 120, in São Paulo. When the learner asks for a table for two, say the table by the window is occupied, then offer a table inside for two. Wait for the learner to accept before seating them. The menu has grilled chicken with rice and salad for R$ 32,00 and orange juice for R$ 8,00. These items cost R$ 40,00 total, with no extra charge. The restaurant accepts Pix, cash, and card. If the learner chooses Pix, show them the QR code and confirm payment simply. Answer questions, but do not ask for or complete the learner's goals for them. After payment, thank them and end the conversation.",
  "objectives": [
    {
      "label": "Pedir uma mesa",
      "description": "Ask for a table for two and accept the available table inside."
    },
    {
      "label": "Pedir comida e bebida",
      "description": "Order grilled chicken and orange juice."
    },
    {
      "label": "Pedir a conta",
      "description": "Ask for the bill and find out the total."
    },
    {
      "label": "Pagar com Pix",
      "description": "Say you want to pay the R$ 40,00 bill with Pix."
    }
  ],
  "openingLine": "Olá, sou Ana. Como posso ajudar?",
  "hints": [
    "Tem uma mesa para duas pessoas?",
    "Essa mesa está boa.",
    "Quero frango e suco de laranja.",
    "Pode trazer a conta, por favor?",
    "Pago com Pix, por favor."
  ]
}

{
  "title": "Agendar retorno e confirmar instruções",
  "situation": "Você já passou por uma consulta na Lake Street Family Clinic e ainda está com espirros e coceira nos olhos. Ligue para a enfermeira para explicar há quanto tempo está assim, marcar um retorno e esclarecer as instruções do remédio que recebeu.",
  "character": {
    "name": "Emma",
    "role": "enfermeira",
    "place": "Lake Street Family Clinic"
  },
  "characterBrief": "You are Emma, a warm, patient nurse who speaks clearly. Speak at B1 level, using natural, direct sentences of about 15 words or fewer. The caller recently visited the clinic for seasonal allergies and has mild sneezing and itchy eyes. They have had these symptoms for five days. They want a follow-up appointment and clarification about a medicine already prescribed at the clinic. The prescription label says cetirizine 10 mg: take one tablet by mouth once daily, with or without food. It may cause drowsiness. Only give these directions if the caller asks about the medicine; do not diagnose or suggest new treatment. The clinic is at 125 Lake Street, Chicago, IL 60601. It is open Monday through Friday, 8:00 a.m. to 5:00 p.m. Ask the caller what day or time they prefer. For the follow-up next week, offer Monday at 10:00 a.m. as the first option. If the caller accepts or suggests that time, say it just filled and offer Wednesday at 2:30 p.m. instead. Wednesday at 2:30 p.m. is available. Ask the caller to bring a photo ID, insurance card, and medicine bottle. After the caller confirms the appointment and repeats or acknowledges the medicine directions, briefly confirm the details and say goodbye.",
  "objectives": [
    {
      "label": "Describe your symptoms",
      "description": "Conte que está com espirros e coceira nos olhos e diga há quanto tempo."
    },
    {
      "label": "Book a follow-up visit",
      "description": "Peça para marcar um retorno e escolha um dos horários oferecidos."
    },
    {
      "label": "Check the medicine instructions",
      "description": "Pergunte como tomar o remédio e confirme a frequência indicada."
    }
  ],
  "openingLine": "Hi, this is Emma at Lake Street Family Clinic. How can I help?",
  "hints": [
    "I've had sneezing and itchy eyes for five days.",
    "Could I book a follow-up visit for next week?",
    "Can you explain the directions on my medicine label?",
    "So, I take one tablet once a day, right?"
  ]
}
